        chatId: null,
        userName: 'You',
        data: { userStats: null, infoBox: null, characters: null },
        settings: null,
        busy: false,
        busySince: 0,
        status: null,
        view: 'trackers',
        invTab: 'onPerson',
        open: { chapter: false },
        locks: {},
        checkpoint: null,
        encounter: null,
        encounterBusy: false,
        encounterActive: false,
        encounterFor: null,
        encounterNotice: null,
        encPick: null,
        encOrders: {},        // pending orders to allies, sent with the next action
        encOrderFor: null,    // the ally an order is being built for
        encExploit: null,     // intel the next action acts on
        encTab: 'physical',
        encOrderTab: 'physical',
        plotBusy: false,
        characterId: null,
        presetSel: '',
        song: null,
        hms: null,
        worldBusy: false,
        encHistory: null,
        showHistory: false,
        expectPush: false,
        expectPushSince: 0,
        avatars: {},
        avatarBusy: {},
