    refreshAction.onClick(() => requestRefresh());
    const openAction = ctx.ui.registerInputBarAction(i18nOpts({ id: 'rpgh-open', label: 'Open RPG Companion' }));
    openAction.onClick(() => tab.activate());
    const fightAction = ctx.ui.registerInputBarAction(i18nOpts({ id: 'rpgh-fight', label: 'Start or resume a fight' }));
    fightAction.onClick(() => openFightChooser());
    const worldAction = ctx.ui.registerInputBarAction(i18nOpts({ id: 'rpgh-world', label: 'Move the world' }));
    worldAction.onClick(() => { if (state.chatId) send({ type: 'world_moves', chatId: state.chatId }); });

